<script setup>
import MdBlocks from '../components/MdBlocks.vue'
// Everything on this page is read from files generated by scripts (see scripts/sync-proof.mjs). No figure is typed in here.
import { computed, nextTick, onMounted, ref } from 'vue'
import { useRoute } from 'vue-router'
import BarRow from '../components/BarRow.vue'
import Skeleton from '../components/Skeleton.vue'
import { liveStatus, loadProof, parseHoldout, readThisFirst } from '../lib/proof.js'
import { parseBlocks } from '../lib/mdparse.js'
import { formatLocalMoney } from '../lib/format.js'
const formatJpy = (n) => formatLocalMoney(n, 'JPY')  // the evaluation is the Tokyo (JPY) pack

const ev = ref(null)
const route = useRoute()
onMounted(async () => {
  ev.value = await loadProof()
  await nextTick()
  // the content arrives after navigation, so honour a #section link (for example from the example-trip note) once it exists
  if (route.hash) document.querySelector(route.hash)?.scrollIntoView({ block: 'start' })
})
const ready = computed(() => ev.value?.state === 'ready')
const d = computed(() => (ready.value ? ev.value.data : null))
const r = computed(() => d.value?.results ?? null)
const m = computed(() => r.value?.metrics ?? null)
const n = computed(() => m.value?.n_trips ?? 0)
const down = (x, nd = 1) => (Math.floor(x * 10 ** nd) / 10 ** nd).toFixed(nd)   // improvements round down, never in the flattering direction
const up = (x, nd = 1) => (Math.ceil(x * 10 ** nd) / 10 ** nd).toFixed(nd)
const pct = (k, total, favourable = true) => (total ? `${(favourable ? down : up)((100 * k) / total)}%` : 'n/a')
const notes = computed(() => (m.value ? readThisFirst(m.value, n.value) : []))
const meta = computed(() => r.value?.meta ?? null)
const dirty = computed(() => /uncommitted/i.test(meta.value?.commit ?? ''))
const stale = computed(() => {
  const evalRev = String(meta.value?.commit ?? '').split(/\s+/)[0]
  const backendRev = String(d.value?.tests?.backend?.revision ?? '').split(/\s+/)[0]
  return evalRev && backendRev && evalRev !== backendRev
})
const frontendStale = computed(() => {
  const frontRev = String(d.value?.tests?.frontend?.git_hash ?? '').split(/\s+/)[0]
  const evalRev = String(meta.value?.commit ?? '').split(/\s+/)[0]
  const backendRev = String(d.value?.tests?.backend?.revision ?? '').split(/\s+/)[0]
  return frontRev && ![evalRev, backendRev].includes(frontRev)
})
const hardening = computed(() => (d.value?.hardeningMd ? parseBlocks(d.value.hardeningMd) : []))
const hardeningResult = computed(() => /\*\*(\d+)\/(\d+) cases passed\*\*/.exec(d.value?.hardeningMd ?? ''))
const live = computed(() => (d.value?.live ? parseBlocks(d.value.live) : null))
const selfcheck = computed(() => (d.value?.selfcheck ? parseBlocks(d.value.selfcheck) : null))
const holdoutStatus = computed(() => liveStatus(d.value?.holdout, promptVersion.value, latestOpts.value))
const holdoutInfo = computed(() => parseHoldout(d.value?.holdout))
const holdoutBlocks = computed(() => blocksOf(d.value?.holdout))
const redteam = computed(() => d.value?.redteam ?? null)
const humanRedteam = computed(() => d.value?.humanRedteam ?? null)
const attackCount = computed(() => redteam.value?.attacks ?? 0)
const rtLiveBlocks = computed(() => blocksOf(d.value?.redteamLive))
const rtLiveStatus = computed(() => liveStatus(d.value?.redteamLive, promptVersion.value, latestOpts.value))
const rtFirstText = computed(() => d.value?.redteamFirst ?? d.value?.redteamLive ?? null)
const rtFirstBlocks = computed(() => blocksOf(rtFirstText.value))
const rtFirstStatus = computed(() => liveStatus(rtFirstText.value, promptVersion.value))
const rtSame = computed(() => !!d.value?.redteamLive && (!d.value?.redteamFirst || d.value.redteamFirst === d.value.redteamLive))
const verification = computed(() => d.value?.verification ?? null)
const baseline = computed(() => d.value?.baseline ?? null)
const itinerary = computed(() => d.value?.itinerary ?? null)
const profileRes = computed(() => d.value?.profiles ?? null)
const itinRows = computed(() => Object.entries(itinerary.value?.cities ?? {}).map(([id, c]) => {
  const a = c.summary.arms, m = c.summary.matched
  return { id, n: c.n_trips, io: a.input_order.feasible, nf: a.nearest_feasible.feasible, opt: a.optimiser.feasible, missed: a.input_order.missed_a_must_visit_where_optimiser_found_a_plan,
    ioB: m.input_order.minutes_saved, nfB: m.nearest_feasible.minutes_saved, ioN: m.input_order.matched_solved, nfN: m.nearest_feasible.matched_solved }
}))
const profRows = computed(() => Object.entries(profileRes.value?.cities ?? {}).flatMap(([id, c]) => Object.values(c.profiles).map((p) => ({ city: id, ...p }))))
const baselineCities = computed(() => Object.entries(baseline.value?.cities ?? {}).map(([id, c]) => {
  const r = c.by_multiple?.['1'] ?? {}
  return { id, n: r.n_eligible, differs: r.joint_differs_from_cheapest, noGain: r.no_gain_vs_cheapest, meanPct: r.percent_gain_vs_cheapest?.mean, vot: c.default_value_of_time,
    penaltyChanged: c.penalty?.changes_when_charge_removed, minutes: c.decomposition_summary?.minutes_saved?.median }
}))
const cityLabel = (c) => c.split('_').map((w) => w[0].toUpperCase() + w.slice(1)).join(' ')
const promptVersion = computed(() => d.value?.promptVersion ?? null)
const blocksOf = (t) => (t ? parseBlocks(t) : null)
const selfcheckHistory = computed(() => blocksOf(d.value?.selfcheckHistory))
const goldFirst = computed(() => blocksOf(d.value?.goldFirst))
const goldAfter = computed(() => blocksOf(d.value?.goldAfter))
const goldMock = computed(() => blocksOf(d.value?.goldMock))
const fp = computed(() => d.value?.llmFingerprint ?? null)
const latestOpts = computed(() => ({ fingerprint: fp.value, enforce: true }))
const staleWhy = (s) => (s.why === 'code' ? 'Made before the last change to the AI code (or without a code stamp); the live script has to be run again.' : `Made with prompt version ${s.version}; the current version is ${promptVersion.value}.`)
const repairSelf = computed(() => (d.value?.repairSelf ? parseBlocks(d.value.repairSelf) : null))
const repairSelfStatus = computed(() => liveStatus(d.value?.repairSelf, promptVersion.value, latestOpts.value))
const selfStatus = computed(() => liveStatus(d.value?.selfcheck, promptVersion.value, latestOpts.value))
const firstStatus = computed(() => liveStatus(d.value?.goldFirst, promptVersion.value))
const afterStatus = computed(() => liveStatus(d.value?.goldAfter, promptVersion.value, latestOpts.value))
const userTest = computed(() => d.value?.userTest ?? { rows: 0, summary: null })
const userTestBlocks = computed(() => (userTest.value.rows && userTest.value.summary ? parseBlocks(userTest.value.summary) : []))
const showRisks = ref(false)
const scenarioPass = computed(() => (r.value?.scenarios ?? []).filter((s) => s.passed).length)
const hv = computed(() => Object.entries(m.value?.hotel_value?.vots ?? {}))
const t = computed(() => m.value?.travel)
const fmt = (x, nd = 1) => (x === null || x === undefined ? 'n/a' : `${down(x, nd)}%`)
const fileNote = computed(() => (ev.value?.missing ?? []).filter((x) => !x.required).map((x) => x.name))
</script>
<template>
  <div class="stack">
    <div><h1>Proof</h1>
      <p class="muted mb-0">What was measured, how, and what it does not show. Everything below is read from files produced by scripts in the repository; nothing is typed in by hand.</p></div>

    <Skeleton v-if="!ev" :lines="6" />
    <div v-else-if="ev.state === 'unavailable'" class="notice notice-warn" role="status" data-testid="proof-unavailable">
      <span class="glyph" aria-hidden="true">!</span><span><strong>Proof is not available in this build.</strong> {{ ev.reason }}</span></div>

    <template v-else>
      <section class="card-soft" data-testid="proof-meta" aria-label="Proof run">
        <div class="row g-3">
          <div class="col-6 col-md-3"><div class="muted small">Evaluation run</div><div class="fw-bold">{{ meta?.date ?? 'unknown' }}</div></div>
          <div class="col-6 col-md-3"><div class="muted small">Code version (git)</div><div class="fw-bold" data-testid="proof-commit">{{ meta?.commit ?? 'unknown' }}</div></div>
          <div class="col-6 col-md-3"><div class="muted small">Mode</div><div class="fw-bold">{{ meta?.mode }} ({{ n }} generated trips)</div></div>
          <div class="col-6 col-md-3"><div class="muted small">Scenarios passing</div><div class="fw-bold">{{ scenarioPass }} of {{ r.scenarios.length }}</div></div>
        </div>
        <div v-if="dirty" class="notice notice-warn mt-3" data-testid="dirty-warning"><span class="glyph" aria-hidden="true">!</span><span>This proof was produced from code with uncommitted changes, so the version above does not identify exactly what was run.</span></div>
        <div v-if="stale" class="notice notice-warn mt-3" data-testid="stale-warning"><span class="glyph" aria-hidden="true">!</span><span>The evaluation revision and verified backend test revision differ. Treat this proof as stale until the full release procedure is rerun for one commit.</span></div>
        <div v-if="frontendStale" class="notice notice-warn mt-3" data-testid="frontend-stale-warning"><span class="glyph" aria-hidden="true">!</span><span>Frontend tests run on a different version. Treat these counts as stale until they are regenerated for this build.</span></div>
        <p v-if="fileNote.length" class="small muted mt-2 mb-0" data-testid="optional-missing">Not available in this build: {{ fileNote.join(', ') }}.</p>
      </section>

      <section v-if="notes.length" class="card-soft" aria-labelledby="rtf-h" data-testid="read-first">
        <h2 id="rtf-h" class="h5">Read this first: the weak and neutral results</h2>
        <ul class="mb-0"><li v-for="x in notes" :key="x">{{ x }}</li></ul>
      </section>

      <section class="card-soft" aria-labelledby="sc-h" data-testid="scenarios">
        <h2 id="sc-h" class="h5">1. The 15 scenarios</h2>
        <p class="small muted">Rows marked "mocked" use a scripted stand-in for the AI: they verify the pipeline, not the model.</p>
        <div class="table-responsive"><table class="table table-honest align-middle mb-0">
          <thead><tr><th scope="col">#</th><th scope="col">Scenario</th><th scope="col">Expected</th><th scope="col">Result</th><th scope="col">Observed</th></tr></thead>
          <tbody><tr v-for="s in r.scenarios" :key="s.num" :data-testid="`scn-${s.num}`">
            <td>{{ s.num }}</td><td>{{ s.name }}<div class="small muted">{{ s.category }}</div></td><td>{{ s.expected }}</td>
            <td><strong :class="s.passed ? 'delta-down' : 'delta-up'"><span aria-hidden="true">{{ s.passed ? '✓' : '✕' }}</span> {{ s.passed ? 'PASS' : 'FAIL' }}</strong></td>
            <td class="small">{{ s.observed }}<span v-if="s.mocked_llm" class="pill ms-1">mocked LLM: verifies the pipeline, not the model</span></td></tr></tbody>
        </table></div>
      </section>

      <section class="card-soft" aria-labelledby="mt-h" data-testid="metrics">
        <h2 id="mt-h" class="h5">2. Measured results ({{ n }} generated trips, sample data)</h2>
        <p class="small muted">Every figure states its N. Percentages that favour the product are rounded down, failure rates and costs up.</p>

        <h3 class="h6">Travel time against two baselines (same sights scheduled by both)</h3>
        <div class="table-responsive"><table class="table table-honest" data-testid="travel-table">
          <thead><tr><th scope="col">Baseline</th><th scope="col" class="num">Comparable trips</th><th scope="col" class="num">Mean reduction</th><th scope="col" class="num">Median</th><th scope="col" class="num">Range</th><th scope="col" class="num">Better / equal / worse</th></tr></thead>
          <tbody><tr v-for="[k, label] in [['naive', 'Input order'], ['nn', 'Nearest neighbour']]" :key="k">
            <th scope="row">{{ label }}</th><td class="num">{{ t[k].n_comparable }} of {{ t[k].n_trips }}</td>
            <td class="num">{{ fmt(t[k].percent_reduction.mean) }}</td><td class="num">{{ fmt(t[k].percent_reduction.median) }}</td>
            <td class="num">{{ fmt(t[k].percent_reduction.min) }} to {{ fmt(t[k].percent_reduction.max) }}</td><td class="num">{{ t[k].better }} / {{ t[k].equal }} / {{ t[k].worse }}</td></tr></tbody></table></div>
        <div class="row g-3 mb-3">
          <div class="col-12 col-md-6" v-for="[k, label] in [['naive', 'Input order'], ['nn', 'Nearest neighbour']]" :key="k">
            <BarRow :label="`${label}: mean reduction`" :value="Math.max(t[k].percent_reduction.mean, 0)" :max="50" :text="fmt(t[k].percent_reduction.mean)" />
            <BarRow :label="`${label}: comparable share of trips`" :value="t[k].n_comparable" :max="t[k].n_trips" :text="`${t[k].n_comparable} of ${t[k].n_trips}`" tone="warn" />
          </div>
        </div>

        <h3 class="h6">Sights scheduled (over {{ m.placement.n_trips }} trips where the optimiser produced a plan; {{ m.placement.requested }} requested)</h3>
        <BarRow v-for="[k, label] in [['solver', 'Optimiser'], ['naive', 'Input order'], ['nn', 'Nearest neighbour']]" :key="k" :label="label" :value="m.placement[k].placed" :max="m.placement.requested" :text="`${m.placement[k].placed} (${pct(m.placement[k].placed, m.placement.requested)})`" />

        <h3 class="h6 mt-3">Independent validator on every itinerary</h3>
        <div class="table-responsive"><table class="table table-honest" data-testid="validator-table">
          <thead><tr><th scope="col">Plans from</th><th scope="col" class="num">Pass</th><th scope="col" class="num">Pass with warnings</th><th scope="col" class="num">Fail</th><th scope="col" class="num">No plan</th><th scope="col" class="num">Fail for a reason beyond a missing must-visit</th></tr></thead>
          <tbody><tr v-for="[k, label] in [['solver', 'Optimiser'], ['naive', 'Input order'], ['nn', 'Nearest neighbour']]" :key="k"><th scope="row">{{ label }} (N={{ m.validation[k].n_trips }})</th>
            <td class="num">{{ m.validation[k].pass }}</td><td class="num">{{ m.validation[k].pass_with_warnings }}</td><td class="num">{{ m.validation[k].fail }}</td><td class="num">{{ m.validation[k].no_plan }}</td>
            <td class="num">{{ m.validation[k].fail_hard_constraint_beyond_missing_must_visit }}</td></tr></tbody></table></div>

        <h3 class="h6">Strict budgets ({{ m.budget.n_strict_trips }} trips) and must-visits ({{ m.must_visit.n_trips_with_must }} trips)</h3>
        <ul class="small">
          <li v-for="[k, label] in [['solver', 'Optimiser'], ['naive', 'Input order'], ['nn', 'Nearest neighbour']]" :key="k">{{ label }}: {{ m.budget[k].within_budget }} of {{ m.budget[k].feasible_plans }} feasible plans within budget (no feasible plan on {{ m.budget[k].no_feasible_plan }}); all must-visits placed on {{ m.must_visit[k].all_placed }}, reported infeasible on {{ m.must_visit[k].reported_infeasible }}, silently dropped on {{ m.must_visit[k].silently_dropped }}.</li>
          <li>Audit of the optimiser's {{ m.must_visit.infeasible_audit.n_infeasible }} infeasibility reports: every stated conflict matched an independent recomputation on {{ m.must_visit.infeasible_audit.all_stated_conflicts_confirmed }}; exhaustive search agreed no schedule exists on {{ m.must_visit.infeasible_audit.brute_force_agrees_no_schedule }} and found one on {{ m.must_visit.infeasible_audit.brute_force_found_a_schedule }}.</li>
        </ul>

        <div id="hotel-value" data-testid="hotel-value" style="scroll-margin-top: 70px">
          <h3 class="h6">Hotel value: how often is the lowest-rate hotel NOT the best by true cost?</h3>
          <p class="small muted">Hotels and rates are fictional and were tuned for the demo. This measures the model's behaviour on sample data, not real hotel markets. Only trips where all three hotels were feasible are counted.</p>
          <BarRow v-for="[v, e] in hv" :key="v" :label="`At ${formatJpy(Number(v))} an hour (N=${e.n_eligible} trips)`" :value="e.cheapest_by_rate_not_best" :max="e.n_eligible" :text="`${e.cheapest_by_rate_not_best} of ${e.n_eligible} (${pct(e.cheapest_by_rate_not_best, e.n_eligible)})`" tone="warn" />
          <p v-if="m.hotel_value.flip" class="small">The best hotel changed somewhere between ¥0 and ¥3,000 an hour in {{ m.hotel_value.flip.n_with_flip }} of {{ m.hotel_value.flip.n_analysed }} analysed trips; the median first change was at about {{ formatJpy(Math.floor(m.hotel_value.flip.first_flip_vot.median)) }} an hour ({{ m.hotel_value.flip.exact_crossing }} exact crossings, {{ m.hotel_value.flip.bisection_estimate }} estimates).</p>
        </div>

        <h3 class="h6 mt-3">Replanning: activities moved without being asked</h3>
        <div v-if="m.replan" data-testid="replan-metrics">
          <BarRow label="Disruption-aware" :value="m.replan.aware.moved.reduce((a, b) => a + b, 0) / Math.max(m.replan.aware.moved.length, 1)" :max="6" :text="`mean ${up(m.replan.aware.moved.reduce((a, b) => a + b, 0) / Math.max(m.replan.aware.moved.length, 1), 2)} (N=${m.replan.aware.moved.length})`" />
          <BarRow label="Naive full re-solve" :value="m.replan.naive.moved.reduce((a, b) => a + b, 0) / Math.max(m.replan.naive.moved.length, 1)" :max="6" :text="`mean ${down(m.replan.naive.moved.reduce((a, b) => a + b, 0) / Math.max(m.replan.naive.moved.length, 1), 2)} (N=${m.replan.naive.moved.length})`" tone="bad" />
          <p class="small">Paired over {{ m.replan.n_both_applied }} scenarios: the disruption-aware strategy moved fewer activities in {{ m.replan.aware_fewer_moves }}, the same in {{ m.replan.same_moves }}, more in {{ m.replan.aware_more_moves }}.</p>
        </div>
        <p class="small mb-0">Solver status over trip solves: {{ Object.entries(m.solver_status.trip_solves).map(([k, v]) => `${k} ${v}`).join(', ') }}.</p>
      </section>

      <section class="card-soft" aria-labelledby="ns-h" data-testid="not-shown">
        <h2 id="ns-h" class="h5">3. What these numbers do not show</h2>
        <ul v-if="d.notShown?.length" class="mb-0">
          <li v-for="x in d.notShown" :key="x">{{ x }}</li>
          <li>The missed optional-sight charge is a judgement-call modelling constant: three hours of the selected city's default value of time, tuned after seeing multi-city results.</li>
        </ul>
        <p v-else class="mb-0 muted">The list was not found in the proof report.</p>
      </section>

      <section class="card-soft" aria-labelledby="rk-h" data-testid="risks">
        <h2 id="rk-h" class="h5">4. Risk, safeguard, test</h2>
        <template v-if="d.risks?.length">
          <p class="small">{{ d.risks.length }} risks are tracked, each with its safeguard and the test(s) that check it.</p>
          <button type="button" class="btn btn-sm btn-outline-secondary mb-2" :aria-expanded="showRisks" @click="showRisks = !showRisks" data-testid="toggle-risks">{{ showRisks ? 'Hide the table' : 'Show the table' }}</button>
          <div v-if="showRisks" class="table-responsive"><table class="table table-honest align-top" data-testid="risk-table">
            <thead><tr><th scope="col">#</th><th scope="col">Risk</th><th scope="col">Safeguard</th><th scope="col">Test</th><th scope="col">Status</th></tr></thead>
            <tbody><tr v-for="x in d.risks" :key="x.n"><td>{{ x.n }}</td><td>{{ x.risk }}</td><td>{{ x.safeguard }}</td><td class="small">{{ x.test }}</td><td>{{ x.status }}</td></tr></tbody></table></div>
        </template>
        <p v-else class="mb-0 muted">The safety log was not found in this build.</p>
      </section>

      <section class="card-soft" aria-labelledby="tt-h" data-testid="tests">
        <h2 id="tt-h" class="h5">Test results</h2>
        <ul class="mb-0">
          <li v-if="d.tests.backend">Backend full suite (pytest): {{ d.tests.backend.passed }} passed, {{ d.tests.backend.failed }} failed, {{ d.tests.backend.skipped }} skipped of {{ d.tests.backend.total }} <span class="muted">({{ d.tests.backend.generated }}, {{ d.tests.backend.revision ?? 'revision unknown' }})</span></li>
          <li v-else class="muted">Backend test summary: not available in this build.</li>
          <li v-if="d.tests.vitest">Frontend unit and component tests (Vitest): {{ d.tests.vitest.passed }} passed, {{ d.tests.vitest.failed }} failed of {{ d.tests.vitest.total }}</li>
          <li v-else class="muted">Frontend unit tests: summary not available in this build.</li>
          <li v-if="d.tests.playwright">End-to-end tests (Playwright, real backend): {{ d.tests.playwright.passed }} passed, {{ d.tests.playwright.failed }} failed of {{ d.tests.playwright.total }}</li>
          <li v-else class="muted">End-to-end test summary: not available in this build.</li>
          <li v-if="d.tests.frontend">Frontend summary file: {{ d.tests.frontend.suites.map((s) => `${s.suite} ${s.passed}/${s.total}`).join(', ') }} <span class="muted">({{ d.tests.frontend.git_hash ?? 'revision unknown' }})</span></li>
          <li v-else class="muted">Frontend combined summary: not available in this build.</li>
        </ul>
      </section>

      <section class="card-soft" aria-labelledby="hd-h" data-testid="hardening">
        <h2 id="hd-h" class="h5">5. API hardening results</h2>
        <p v-if="hardeningResult" class="mb-2"><strong>{{ hardeningResult[1] }} of {{ hardeningResult[2] }}</strong> abuse cases passed.</p>
        <details v-if="hardening.length"><summary class="fw-semibold">Every case</summary>
          <template v-for="(b, i) in hardening" :key="i">
            <h3 v-if="b.type === 'h'" class="h6 mt-3">{{ b.text }}</h3>
            <p v-else-if="b.type === 'p'" class="small">{{ b.text }}</p>
            <div v-else-if="b.type === 'table'" class="table-responsive"><table class="table table-honest"><thead><tr><th v-for="h in b.head" :key="h" scope="col">{{ h }}</th></tr></thead>
              <tbody><tr v-for="(row, j) in b.rows" :key="j"><td v-for="(c, k) in row" :key="k">{{ c }}</td></tr></tbody></table></div>
            <ul v-else-if="b.type === 'ul'" class="small"><li v-for="x in b.items" :key="x">{{ x }}</li></ul>
          </template></details>
        <p v-else class="mb-0 muted">The hardening results were not found in this build.</p>
      </section>

      <section class="card-soft" aria-labelledby="cl-h" data-testid="claims">
        <h2 id="cl-h" class="h5">6. Claim sentences generated from the numbers</h2>
        <p class="small muted">Verbatim from README-claims.md. Each carries its N and its caveat.</p>
        <ul v-if="d.claims?.length" class="mb-0"><li v-for="c in d.claims" :key="c.id" class="mb-2" :data-testid="`claim-${c.id}`">{{ c.text }}</li></ul>
        <p v-else class="mb-0 muted">The claim sentences were not found in this build.</p>
      </section>

      <section id="red-team" class="card-soft" aria-labelledby="rt-h" data-testid="red-team">
        <h2 id="rt-h" class="h5">Red team: attacks on the AI paths</h2>
        <template v-if="redteam">
          <p class="mb-2" data-testid="rt-simulated"><strong>Simulated models, not a real model.</strong> {{ redteam.runs }} runs: {{ attackCount }} attacks in English, Korean, Chinese and Malay, each sent through the real pipeline for every city to a deliberately gullible mock (it obeys the injection) and a harmless mock. A run counts as "affected" only if the final result a user would see changed: a safety flag set, a place from another city or from nowhere scheduled, an invented number, or the system prompt, a key or another user's data shown.</p>
          <div class="table-responsive"><table class="table table-honest" data-testid="rt-table"><thead><tr><th scope="col">Category</th><th scope="col">Runs</th><th scope="col">Gullible mock tried to comply</th><th scope="col">Final result affected</th></tr></thead>
            <tbody><tr v-for="(v, k) in redteam.by_category" :key="k"><th scope="row">{{ k.replaceAll('_', ' ') }}</th><td>{{ v.runs }}</td><td>{{ v.raw_tried_to_comply }}</td><td>{{ v.final_affected }}</td></tr></tbody></table></div>
          <p class="small mb-2">By language: <span v-for="(v, k) in redteam.by_language" :key="k" class="me-3">{{ k }}: {{ v.final_affected }} of {{ v.runs }} affected</span></p>
          <p class="small mb-2">By city: <span v-for="(v, k) in redteam.by_city" :key="k" class="me-3">{{ cityLabel(k) }}: {{ v.final_affected }} of {{ v.runs }} affected</span></p>
          <h3 class="h6 mt-3">Found and fixed</h3>
          <ul class="small" data-testid="rt-fixed"><li v-for="f in redteam.found_and_fixed" :key="f.what"><strong>{{ f.what }}.</strong> Before: {{ f.before }}. After: {{ f.after }}. Fix: {{ f.fix }}</li><li v-if="!redteam.found_and_fixed?.length">Nothing was found.</li></ul>
          <p class="small muted">These counts test the code around the model. They say nothing about a real model; the live result is below only if it was run for this version.</p>
        </template>
        <p v-else class="mb-2" data-testid="rt-none"><strong>Not run on this version.</strong> No red-team results are part of this build.</p>
        <p v-if="humanRedteam" class="small mb-2" data-testid="rt-human"><strong>Human attempts: {{ humanRedteam.n }}, final result wrong in {{ humanRedteam.wrong }}.</strong> Informal, small N: friends trying to break the AI box by hand (<code>docs/user-test/HUMAN-REDTEAM.md</code>). It finds obvious holes; it is not coverage.</p>
        <h3 class="h6 mt-3">Real model (27 attacks, one city each, one run each)</h3>
        <div class="row g-3" data-testid="rt-live-cols">
          <div class="col-12 col-lg-6" data-testid="rt-live-first">
            <h4 class="h6">First live run</h4>
            <p v-if="rtFirstStatus.state === 'missing'" class="small mb-0" data-testid="rt-live-none"><strong>Not run on this version.</strong> The opt-in script <code>backend/scripts/redteam_live.py</code> sends a sample of the same attacks to a real model; no live red-team result exists yet.</p>
            <template v-else>
              <p v-if="rtFirstStatus.state === 'stale'" class="small muted" data-testid="rt-live-historical"><strong>Historical record, kept as it was.</strong> {{ staleWhy(rtFirstStatus) }}</p>
              <MdBlocks :blocks="rtFirstBlocks" />
            </template>
          </div>
          <div class="col-12 col-lg-6" data-testid="rt-live-latest">
            <h4 class="h6">Latest live run</h4>
            <p v-if="rtLiveStatus.state === 'missing'" class="small mb-0"><strong>Not run yet.</strong></p>
            <p v-else-if="rtSame" class="small mb-0" data-testid="rt-live-same"><strong>Not re-run since the first run.</strong> Code changes made after the first run (see "Found and fixed") are tested with mocks only.</p>
            <p v-else-if="rtLiveStatus.state === 'stale'" class="small mb-0" data-testid="rt-latest-stale"><strong>Not run on this version.</strong> {{ staleWhy(rtLiveStatus) }}</p>
            <div v-else data-testid="rt-live"><MdBlocks :blocks="rtLiveBlocks" /></div>
          </div>
        </div>
      </section>

      <section v-if="itinRows.length" id="itinerary" class="card-soft" aria-labelledby="it-h" data-testid="itinerary-study">
        <h2 id="it-h" class="h5">Itinerary planning, separate from hotel choice</h2>
        <p class="small muted">Same trips, trip's own (fictional) hotel, data, constraints, estimated travel times and scoring for every arm. "Feasible" means every must-visit placed and no failed independent check. Matched routing re-solves the optimiser for exactly the sights a baseline placed, so any difference is order and day only. Seeded synthetic trips on sample data; not user-tested; each city on its own.</p>
        <div class="table-responsive"><table class="table table-honest align-middle" data-testid="itinerary-table">
          <thead><tr><th scope="col">City</th><th scope="col" class="num">Trips</th><th scope="col" class="num">Input order feasible</th><th scope="col" class="num">Nearest feasible feasible</th><th scope="col" class="num">Optimiser feasible</th><th scope="col" class="num">Input order missed a must-visit where a plan existed</th><th scope="col" class="num">Matched vs input order: less / same / more travel</th><th scope="col" class="num">Matched vs nearest feasible: less / same / more travel</th></tr></thead>
          <tbody><tr v-for="r in itinRows" :key="r.id" :data-testid="`itin-${r.id}`"><th scope="row">{{ cityLabel(r.id) }}</th><td class="num">{{ r.n }}</td><td class="num">{{ r.io }}</td><td class="num">{{ r.nf }}</td><td class="num">{{ r.opt }}</td><td class="num">{{ r.missed }}</td>
            <td class="num">{{ r.ioB.better }} / {{ r.ioB.equal }} / {{ r.ioB.worse }} (median {{ r.ioB.median }} min, N={{ r.ioN }})</td><td class="num">{{ r.nfB.better }} / {{ r.nfB.equal }} / {{ r.nfB.worse }} (median {{ r.nfB.median }} min, N={{ r.nfN }})</td></tr></tbody></table></div>
        <p class="small mb-2" data-testid="itinerary-honest">Against the nearest-feasible heuristic the typical difference is small: many trips tie. The clearest verified benefit is feasibility (keeping every must-visit) and reordering a listed-order plan, not a large saving over a careful heuristic.</p>
        <details v-if="profRows.length" class="small" data-testid="profile-study"><summary class="fw-semibold">Do travel profiles change plans?</summary>
          <div class="table-responsive mt-2"><table class="table table-honest align-middle mb-0"><thead><tr><th scope="col">City</th><th scope="col">Profile</th><th scope="col" class="num">Comparable trips</th><th scope="col" class="num">Infeasible with profile</th><th scope="col" class="num">Same plan as no profile</th><th scope="col" class="num">Median change in est. travel (min)</th></tr></thead>
            <tbody><tr v-for="p in profRows" :key="p.city + p.label"><th scope="row">{{ cityLabel(p.city) }}</th><td>{{ p.label }}</td><td class="num">{{ p.comparable_trips }}</td><td class="num">{{ p.infeasible_with_profile }}</td><td class="num">{{ p.same_plan_as_no_profile }} of {{ p.feasible }}</td><td class="num">{{ p.changed_minutes.median ?? '-' }}</td></tr></tbody></table></div></details>
      </section>

      <section v-if="baselineCities.length" id="baselines" class="card-soft" aria-labelledby="bl-h" data-testid="baselines">
        <h2 id="bl-h" class="h5">Fair baselines: cheapest first, convenience first, joint</h2>
        <p class="small muted">Same sights, rules, estimated travel times and objective for all three; only the way the hotel is chosen differs. Seeded synthetic trips on sample data with made-up hotels, at each city's own default value of time. Not user-tested. Each city is reported on its own.</p>
        <div class="table-responsive"><table class="table table-honest align-middle" data-testid="baseline-table">
          <thead><tr><th scope="col">City</th><th scope="col" class="num">Eligible trips</th><th scope="col" class="num">Joint pick differs from cheapest</th><th scope="col" class="num">No gain over cheapest</th><th scope="col" class="num">Mean score gain over cheapest</th><th scope="col" class="num">Pick changes if the missed-sight charge is removed</th></tr></thead>
          <tbody><tr v-for="c in baselineCities" :key="c.id" :data-testid="`baseline-${c.id}`"><th scope="row">{{ cityLabel(c.id) }}</th><td class="num">{{ c.n }}</td><td class="num">{{ c.differs }}</td><td class="num">{{ c.noGain }}</td><td class="num">{{ c.meanPct }}%</td><td class="num">{{ c.penaltyChanged }}</td></tr></tbody></table></div>
        <p class="small mb-2" data-testid="baseline-honest">In most sample trips the cheapest hotel is also the best overall choice. Joint optimisation helps only when a pricier hotel saves enough travel time at the chosen value of time; the rows above include the cities where it made little or no difference.</p>
        <details class="small" data-testid="cost-terms"><summary class="fw-semibold">What each number means</summary>
          <ul class="mb-0 mt-2">
            <li><strong>Monetary spending</strong>: rooms + admissions + estimated transport. Rooms use made-up sample rates; no hotel price is verified.</li>
            <li><strong>Estimated transport</strong>: fares estimated from the sample data, not quotes.</li>
            <li><strong>Travel time as money</strong>: estimated minutes (from straight-line distances) × the value of an hour you chose. A weighting, not a charge.</li>
            <li><strong>Unknown admission</strong>: left out of every money figure. Inside the optimiser's score only, it is valued at a placeholder.</li>
            <li><strong>Missed-sight charge</strong>: a fixed amount per optional sight left out, used only to weigh the plan.</li>
            <li><strong>Optimisation score</strong>: spending + travel time as money + missed-sight charges. Lower is better. It is never what you pay.</li>
          </ul></details>
      </section>

      <section v-if="verification" id="data-verification" class="card-soft" aria-labelledby="dv-h" data-testid="data-verification">
        <h2 id="dv-h" class="h5">Data verification</h2>
        <p class="mb-2" data-testid="dv-sentence"><strong>{{ verification.readme_sentence }}.</strong></p>
        <p class="small muted">Counted by a script from the data files. "Source-checked" means an official page stated the value (the page and date are recorded in the data); "human-verified" means a person confirmed it. A field is a checkable group (hours and closing days, admission, advance booking, coordinates, name and area), an alias spelling, or a hotel rate; made-up hotel rates and our own visit-duration estimates are "not applicable".</p>
        <div class="table-responsive"><table class="table table-honest" data-testid="dv-table"><thead><tr><th scope="col">City</th><th scope="col">Unchecked</th><th scope="col">Source-checked</th><th scope="col">Human-verified</th><th scope="col">Not applicable</th></tr></thead>
          <tbody><tr v-for="(v, c) in verification.cities" :key="c"><th scope="row">{{ cityLabel(c) }}</th><td>{{ v.unchecked }}</td><td>{{ v.source_checked }}</td><td>{{ v.human_verified }}</td><td>{{ v.not_applicable }}</td></tr></tbody></table></div>
      </section>

      <section id="user-test" class="card-soft" aria-labelledby="ut-h" data-testid="user-test">
        <h2 id="ut-h" class="h5">User test</h2>
        <p v-if="!userTest.rows" class="mb-0" data-testid="user-test-none"><strong>Not run yet.</strong> No one outside the team has tried the app under the written protocol, so there are no user figures here. Nothing is filled in until real results exist.</p>
        <template v-else>
          <p class="mb-2"><strong>{{ userTest.rows }}</strong> participant(s). Informal, small N, self-reported where stated: indicative, not a benchmark. Generated from the results file by a script.</p>
          <template v-for="(b, i) in userTestBlocks" :key="i">
            <h3 v-if="b.type === 'h'" class="h6 mt-3">{{ b.text }}</h3>
            <p v-else-if="b.type === 'p'" class="small">{{ b.text }}</p>
            <div v-else-if="b.type === 'table'" class="table-responsive"><table class="table table-honest"><thead><tr><th v-for="h in b.head" :key="h" scope="col">{{ h }}</th></tr></thead>
              <tbody><tr v-for="(row, j) in b.rows" :key="j"><td v-for="(c, k) in row" :key="k">{{ c }}</td></tr></tbody></table></div>
            <ul v-else-if="b.type === 'ul'" class="small"><li v-for="x in b.items" :key="x">{{ x }}</li></ul>
          </template>
        </template>
      </section>

      <section class="card-soft" aria-labelledby="lv-h" data-testid="live-eval">
        <h2 id="lv-h" class="h5">7. Live AI evidence</h2>
        <p class="small" data-testid="live-framing"><strong>Tuned on these checks; small sample; one model, through a third-party gateway.</strong> The planner and the checks around the AI are tested with scripted stand-ins; this card is the only place a real model's behaviour is reported.</p>

        <h3 class="h6 mt-3">Smoke test (20 checks)</h3>
        <p v-if="selfStatus.state === 'missing'" class="mb-2" data-testid="selfcheck-none"><strong>Not run on this version.</strong> No self-check report is part of this build.</p>
        <p v-else-if="selfStatus.state === 'stale'" class="mb-2" data-testid="selfcheck-stale"><strong>Not run on this version.</strong> {{ staleWhy(selfStatus) }}</p>
        <div v-else class="mb-2" data-testid="selfcheck"><MdBlocks :blocks="selfcheck" /></div>
        <details v-if="selfcheckHistory" class="small mb-2" open data-testid="selfcheck-history"><summary class="fw-semibold">Run history: every run, its root cause and its fix</summary><div class="mt-2"><MdBlocks :blocks="selfcheckHistory" /></div></details>

        <h3 class="h6 mt-3">AI repair and travel-style smoke test (16 checks)</h3>
        <p v-if="repairSelfStatus.state === 'missing'" class="mb-2" data-testid="repair-selfcheck-none"><strong>Not run on this version.</strong> No report for the AI repair and travel-style features is part of this build.</p>
        <p v-else-if="repairSelfStatus.state === 'stale'" class="mb-2" data-testid="repair-selfcheck-stale"><strong>Not run on this version.</strong> {{ staleWhy(repairSelfStatus) }}</p>
        <div v-else class="mb-2" data-testid="repair-selfcheck"><MdBlocks :blocks="repairSelf" /></div>

        <h3 class="h6 mt-3">Gold set: 48 hand-written prompts (12 per city, never pooled)</h3>
        <div class="row g-3" data-testid="gold-live">
          <div class="col-12 col-lg-6" data-testid="gold-first">
            <h4 class="h6">First run</h4>
            <p v-if="firstStatus.state === 'missing'" class="small mb-0"><strong>Not run yet.</strong> Run <code>score_gold.py --live --label first-run</code> and copy the file to <code>docs/eval/gold-results-live-first-run.md</code>.</p>
            <template v-else>
              <p v-if="firstStatus.state === 'stale'" class="small muted" data-testid="gold-first-historical"><strong>Historical record, kept as it was.</strong> {{ staleWhy(firstStatus) }}</p>
              <MdBlocks :blocks="goldFirst" />
            </template>
          </div>
          <div class="col-12 col-lg-6" data-testid="gold-after">
            <h4 class="h6">Latest run (final)</h4>
            <p v-if="afterStatus.state === 'missing'" class="small mb-0"><strong>Not run yet.</strong> Run <code>score_gold.py --live --label final</code> after the last code change and copy the file to <code>docs/eval/gold-results-live-final.md</code>; the first run is never overwritten.</p>
            <p v-else-if="afterStatus.state === 'stale'" class="small mb-0"><strong>Not run on this version.</strong> {{ staleWhy(afterStatus) }}</p>
            <MdBlocks v-else :blocks="goldAfter" />
          </div>
        </div>
        <p class="small muted mt-2 mb-0">The hand-written prompts and their expected answers were written by the same person who built the pipeline, and the pipeline was tuned on similar checks, so a high score here is optimistic. Many fields (the wrong-city stop, place-name matching) are decided by code, not the model.</p>

        <template v-if="holdoutStatus.state === 'current' && holdoutInfo">
          <p class="small mt-3 mb-1" data-testid="holdout"><strong>Independent holdout: {{ holdoutInfo.n }} prompts written by {{ holdoutInfo.role }}, small sample.</strong> Written before any run, by someone other than the builder; one model.</p>
          <details class="small mb-2"><summary>Independent holdout results</summary><div class="mt-2"><MdBlocks :blocks="holdoutBlocks" /></div></details>
        </template>
        <p v-else-if="holdoutStatus.state === 'stale'" class="small mt-3 mb-1" data-testid="holdout-stale"><strong>Independent holdout: not run on this version.</strong></p>
        <p v-else class="small mt-3 mb-1" data-testid="holdout-none"><strong>Independent holdout: not run.</strong> It needs prompts written by someone other than the builder (<code>docs/eval/HOLDOUT-INSTRUCTIONS.md</code>).</p>
        <details v-if="goldMock" class="small mt-3" data-testid="gold-mock"><summary class="fw-semibold">Rule-based baseline, not a model</summary>
          <p class="mb-1 mt-2"><strong>This is not AI accuracy.</strong> It is a deterministic stand-in (regexes and alias scanning) that shows the scoring works and gives a floor to compare a model against.</p><MdBlocks :blocks="goldMock" /></details>

        <template v-if="live"><h3 class="h6 mt-3">Larger live evaluation</h3><MdBlocks :blocks="live" /></template>
        <p class="small muted mt-2 mb-0" data-testid="live-source">Model name and endpoint host are copied from the generated files above, never from a fixed provider name. If the files say "third-party relay", the cleaned text and computed facts passed through that gateway to the model provider.</p>
      </section>
    </template>
  </div>
</template>
